#!/bin/bash
# The pre-grasp room-hold guards (2026-10-31 night, user: "go ahead all the fixes and check them in the Isaac
# simulations") -- after the 10-31 evening hardware valve flight (archive/wb_valve_turning_flight_20261031).
# Harness = the 10-30/31 v2 control runs' (archive/valve_safety_fixes_20261030/sim/chain.sh): the v2 valve at
# 0.072 N.m (drive model), the shipped valve sim yaml (regenerated by try_valve.sh from the generator, now with
# the base gate / leash / descent guard / arm guards before the handle), raw mocap, headless, the ARM GS flying
# Ready / Turn / Exit by itself (--gs-auto, as on hardware -- its automatic Ready retries the new "wait for it to
# settle" refusals), each run stopped 4 s after the exit.
#   setsid nohup bash chain.sh [job ...] > ../chain.out 2>&1 &      (touch ../runs/STOP to skip the rest)
C=~/fsc_PegasusSimulator/docs/docs_aerial_manipulator/archive/valve_turning_20261015
HERE="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)"
R="$HERE/../runs"; mkdir -p "$R"
export PL_RUNS_DIR="$R"
export PEGASUS_VALVE_USD=~/fsc_PegasusSimulator/extensions/fsc_aerial_manipulation/fsc_aerial_manipulation/rotorcraft/assets/Valve_Assembly_v2.usda
export PEGASUS_VALVE_FRICTION=0.072 PEGASUS_VALVE_FRICTION_MODEL=drive PEGASUS_VALVE_DAMPING=0.0
DRV=~/fsc_PegasusSimulator/docs/docs_aerial_manipulator/archive/wb_valve_turning_flight_20261028/tools/driver
clean() { ~/ros2_ws/src/fsc_autopilot_ros2/scripts/isaacsim/stop_isaacsim_stack.sh > /dev/null 2>&1; ~/fsc_PegasusSimulator/scripts/kill_stale_sim_processes.sh -y > /dev/null 2>&1; sleep 5; }
fly() { tag=$1; shift
  echo "$(date +%H:%M:%S) start $tag noise=${PEGASUS_PLANT_FORCE_NOISE:-none} $*"
  ARM_GS_AUTO_STEPS=true ARM_GS_AUTO_EXIT_DELAY=0.2 RELEASE_AT_OPEN=0 \
    PL_PUSH_TOOLS="$DRV" PL_DRIVER_ARGS="--gs-auto --stop-after-exit --stop-hold 4" bash $C/tools/try_valve.sh "$tag" "$@"; }
gs() { [[ -e "$R/STOP" ]] && { echo "STOP file: skipping $1"; return; }; clean; fly "$@"; }
SOFT="wb_ky_psi_before_grip=0.2484 wb_dy_psi_before_grip=0.2903 wb_stuck_hold_j4_before_grip=false"

run() {   # job names: nom1 nom2 s2 s3 s4 soft_s2 soft_s3 leash dguard q3
  case $1 in
    nom1|nom2) unset PEGASUS_PLANT_FORCE_NOISE; gs rh_$1 ;;
    s2|s3|s4) export PEGASUS_PLANT_FORCE_NOISE="0.32,0.12,${1#s}"; gs rh_$1 ;;
    # Step 2's A/B in Isaac: the pre-grasp heading back to the soft interaction set (the grip schedule's
    # heading change off), the damping raise kept -- against rh_s2 / rh_s3 (the shipped stiff set)
    soft_s2|soft_s3) export PEGASUS_PLANT_FORCE_NOISE="0.32,0.12,${1#soft_s}"; gs rh_$1 $SOFT ;;
    # FORCED TRIPS (temporary limits inside what Isaac reaches, so each guard fires once in the real stack):
    # the leash at 15 mm with the settle gate at 10 mm (holds reach 8-31 mm under the drift model)
    leash) export PEGASUS_PLANT_FORCE_NOISE="0.32,0.12,2"
           gs rh_leash push_pull_room_hold_leash=0.015 push_pull_ready_max_com_err=0.010 ;;
    # the descent guard at 10 mm (nominal descents reach 6-13 mm)
    dguard) unset PEGASUS_PLANT_FORCE_NOISE; gs rh_dguard push_pull_guard_ready_com_err=0.010 ;;
    # the static q3 guard at 26 deg, above the turn pose's 25: trips in the room hold above the handle
    q3) unset PEGASUS_PLANT_FORCE_NOISE; gs rh_q3 push_pull_guard_q3_min_deg=26.0 ;;
    *) echo "unknown job $1" ;;
  esac
}
for j in "${@:-nom1 s2 s3 s4 soft_s2 soft_s3 nom2 leash dguard q3}"; do for k in $j; do run "$k"; done; done
clean
echo "$(date +%H:%M:%S) CHAIN DONE"
